import pandas as pd
import numpy as np
import json
import os

# ─── Load Data ───
df = pd.read_csv('/app/benchmark/data.csv', parse_dates=['Sale_Date'])

# ─── Derived Columns ───
df['Year'] = df['Sale_Date'].dt.year
df['Month'] = df['Sale_Date'].dt.to_period('M').astype(str)
df['Resale_Retail_Ratio'] = df['Resale_Price_USD'] / df['Retail_Price_USD']
df['Above_Retail'] = df['Resale_Price_USD'] > df['Retail_Price_USD']

# ─── KPIs ───
avg_profit_margin = round(df['Profit_Margin_USD'].mean(), 2)
resale_premium_rate = round(df['Above_Retail'].mean() * 100, 1)
avg_days_inventory = round(df['Days_in_Inventory'].mean(), 1)
avg_resale_retail_ratio = round(df['Resale_Retail_Ratio'].mean(), 3)

# Top-performing colorway by avg profit margin
colorway_margin = df.groupby('Colorway')['Profit_Margin_USD'].mean()
top_colorway = colorway_margin.idxmax()
top_colorway_margin = round(colorway_margin.max(), 2)

# ─── Section 1: Market Overview ───
total_transactions = len(df)
date_min = df['Sale_Date'].min().strftime('%Y-%m-%d')
date_max = df['Sale_Date'].max().strftime('%Y-%m-%d')
avg_retail = round(df['Retail_Price_USD'].mean(), 2)
avg_resale = round(df['Resale_Price_USD'].mean(), 2)
median_profit = round(df['Profit_Margin_USD'].median(), 2)
std_profit = round(df['Profit_Margin_USD'].std(), 2)
pct_positive = round((df['Profit_Margin_USD'] > 0).mean() * 100, 1)
pct_negative = round((df['Profit_Margin_USD'] < 0).mean() * 100, 1)
pct_breakeven = round((df['Profit_Margin_USD'] == 0).mean() * 100, 1)

# Profit margin distribution buckets
margin_bins = [df['Profit_Margin_USD'].min() - 1, -100, -50, 0, 50, 100, 200, 300, 500, df['Profit_Margin_USD'].max() + 1]
margin_labels = ['< -$100', '-$100 to -$50', '-$50 to $0', '$0 to $50', '$50 to $100', '$100 to $200', '$200 to $300', '$300 to $500', '> $500']
margin_dist = pd.cut(df['Profit_Margin_USD'], bins=margin_bins, labels=margin_labels).value_counts().sort_index()

# Yearly summary
yearly_summary = df.groupby('Year').agg(
    Transactions=('Transaction_ID', 'count'),
    Avg_Retail=('Retail_Price_USD', 'mean'),
    Avg_Resale=('Resale_Price_USD', 'mean'),
    Avg_Margin=('Profit_Margin_USD', 'mean'),
    Avg_Days=('Days_in_Inventory', 'mean')
).round(2)

# ─── Section 2: Model & Colorway Analysis ───
model_stats = df.groupby('Shoe_Model').agg(
    Transactions=('Transaction_ID', 'count'),
    Avg_Retail=('Retail_Price_USD', 'mean'),
    Avg_Resale=('Resale_Price_USD', 'mean'),
    Avg_Margin=('Profit_Margin_USD', 'mean'),
    Median_Margin=('Profit_Margin_USD', 'median'),
    Avg_Ratio=('Resale_Retail_Ratio', 'mean'),
    Above_Retail_Pct=('Above_Retail', 'mean')
).round(2).sort_values('Avg_Margin', ascending=False).reset_index()

colorway_stats = df.groupby('Colorway').agg(
    Transactions=('Transaction_ID', 'count'),
    Avg_Retail=('Retail_Price_USD', 'mean'),
    Avg_Resale=('Resale_Price_USD', 'mean'),
    Avg_Margin=('Profit_Margin_USD', 'mean'),
    Median_Margin=('Profit_Margin_USD', 'median'),
    Avg_Ratio=('Resale_Retail_Ratio', 'mean'),
    Above_Retail_Pct=('Above_Retail', 'mean')
).round(2).sort_values('Avg_Margin', ascending=False).reset_index()

# Model-Colorway heatmap data
model_colorway = df.groupby(['Shoe_Model', 'Colorway'])['Profit_Margin_USD'].mean().round(2).unstack(fill_value=0)

# ─── Section 3: Condition Impact ───
condition_stats = df.groupby('Condition').agg(
    Transactions=('Transaction_ID', 'count'),
    Avg_Retail=('Retail_Price_USD', 'mean'),
    Avg_Resale=('Resale_Price_USD', 'mean'),
    Avg_Margin=('Profit_Margin_USD', 'mean'),
    Median_Margin=('Profit_Margin_USD', 'median'),
    Avg_Ratio=('Resale_Retail_Ratio', 'mean'),
    Above_Retail_Pct=('Above_Retail', 'mean'),
    Avg_Days=('Days_in_Inventory', 'mean')
).round(2).reset_index()

# Condition by model
condition_model = df.groupby(['Shoe_Model', 'Condition'])['Profit_Margin_USD'].mean().round(2).unstack(fill_value=0)

# Condition premium gaps
ds_margin = condition_stats.loc[condition_stats['Condition'].str.contains('Deadstock'), 'Avg_Margin'].values[0]
vnds_margin = condition_stats.loc[condition_stats['Condition'].str.contains('VNDS'), 'Avg_Margin'].values[0]
used_margin = condition_stats.loc[condition_stats['Condition'].str.contains('Used'), 'Avg_Margin'].values[0]
ds_vnds_gap = round(ds_margin - vnds_margin, 2)
vnds_used_gap = round(vnds_margin - used_margin, 2)
ds_used_gap = round(ds_margin - used_margin, 2)

# ─── Section 4: Channel Performance ───
channel_stats = df.groupby('Sales_Channel').agg(
    Transactions=('Transaction_ID', 'count'),
    Avg_Retail=('Retail_Price_USD', 'mean'),
    Avg_Resale=('Resale_Price_USD', 'mean'),
    Avg_Margin=('Profit_Margin_USD', 'mean'),
    Median_Margin=('Profit_Margin_USD', 'median'),
    Avg_Ratio=('Resale_Retail_Ratio', 'mean'),
    Above_Retail_Pct=('Above_Retail', 'mean'),
    Avg_Days=('Days_in_Inventory', 'mean'),
    Median_Days=('Days_in_Inventory', 'median')
).round(2).reset_index().sort_values('Avg_Margin', ascending=False)

# Velocity-efficiency matrix
channel_stats['Daily_Margin'] = round(channel_stats['Avg_Margin'] / channel_stats['Avg_Days'], 2)

# Channel by condition
channel_condition = df.groupby(['Sales_Channel', 'Condition']).agg(
    Avg_Margin=('Profit_Margin_USD', 'mean'),
    Avg_Days=('Days_in_Inventory', 'mean')
).round(2).reset_index()

# ─── Section 5: Temporal Trends ───
monthly_trends = df.groupby('Month').agg(
    Transactions=('Transaction_ID', 'count'),
    Avg_Resale=('Resale_Price_USD', 'mean'),
    Avg_Margin=('Profit_Margin_USD', 'mean'),
    Avg_Days=('Days_in_Inventory', 'mean'),
    Avg_Ratio=('Resale_Retail_Ratio', 'mean')
).round(2).reset_index()
monthly_trends = monthly_trends.sort_values('Month')

# Quarterly aggregation for cleaner trend view
df['Quarter'] = df['Sale_Date'].dt.to_period('Q').astype(str)
quarterly_trends = df.groupby('Quarter').agg(
    Transactions=('Transaction_ID', 'count'),
    Avg_Resale=('Resale_Price_USD', 'mean'),
    Avg_Margin=('Profit_Margin_USD', 'mean'),
    Avg_Days=('Days_in_Inventory', 'mean'),
    Avg_Ratio=('Resale_Retail_Ratio', 'mean')
).round(2).reset_index()

# Yearly condition mix
yearly_condition = df.groupby(['Year', 'Condition']).size().unstack(fill_value=0)
yearly_condition_pct = yearly_condition.div(yearly_condition.sum(axis=1), axis=0).round(3) * 100

# Seasonal patterns by month-of-year
df['MonthOfYear'] = df['Sale_Date'].dt.month
seasonal = df.groupby('MonthOfYear').agg(
    Avg_Margin=('Profit_Margin_USD', 'mean'),
    Avg_Resale=('Resale_Price_USD', 'mean'),
    Avg_Days=('Days_in_Inventory', 'mean'),
    Transactions=('Transaction_ID', 'count')
).round(2).reset_index()

# ─── Build HTML ───

# Helper: format dollar
def fmt_dollar(val):
    if val < 0:
        return f"<span style='color:#ef4444'>-${abs(val):,.2f}</span>"
    elif val > 0:
        return f"<span style='color:#22c55e'>+${val:,.2f}</span>"
    return "$0.00"

def fmt_pct(val):
    return f"{val:.1f}%"

def fmt_ratio(val):
    return f"{val:.3f}x"

# Chart.js data as JSON strings
margin_dist_labels = json.dumps(margin_dist.index.tolist())
margin_dist_values = json.dumps(margin_dist.values.tolist())

model_labels = json.dumps(model_stats['Shoe_Model'].tolist())
model_margins = json.dumps(model_stats['Avg_Margin'].tolist())
model_ratios = json.dumps(model_stats['Avg_Ratio'].tolist())
model_txns = json.dumps(model_stats['Transactions'].tolist())

colorway_labels = json.dumps(colorway_stats['Colorway'].tolist())
colorway_margins = json.dumps(colorway_stats['Avg_Margin'].tolist())
colorway_ratios = json.dumps(colorway_stats['Avg_Ratio'].tolist())
colorway_txns = json.dumps(colorway_stats['Transactions'].tolist())

condition_labels_json = json.dumps(condition_stats['Condition'].tolist())
condition_margins = json.dumps(condition_stats['Avg_Margin'].tolist())
condition_ratios = json.dumps(condition_stats['Avg_Ratio'].tolist())
condition_above = json.dumps(condition_stats['Above_Retail_Pct'].tolist())
condition_days = json.dumps(condition_stats['Avg_Days'].tolist())

channel_labels = json.dumps(channel_stats['Sales_Channel'].tolist())
channel_margins = json.dumps(channel_stats['Avg_Margin'].tolist())
channel_days = json.dumps(channel_stats['Avg_Days'].tolist())
channel_txns = json.dumps(channel_stats['Transactions'].tolist())
channel_above = json.dumps(channel_stats['Above_Retail_Pct'].tolist())
channel_ratios = json.dumps(channel_stats['Avg_Ratio'].tolist())

monthly_labels = json.dumps(monthly_trends['Month'].tolist())
monthly_margins = json.dumps(monthly_trends['Avg_Margin'].tolist())
monthly_resale = json.dumps(monthly_trends['Avg_Resale'].tolist())
monthly_days = json.dumps(monthly_trends['Avg_Days'].tolist())
monthly_txns = json.dumps(monthly_trends['Transactions'].tolist())

quarterly_labels = json.dumps(quarterly_trends['Quarter'].tolist())
quarterly_margins = json.dumps(quarterly_trends['Avg_Margin'].tolist())
quarterly_resale = json.dumps(quarterly_trends['Avg_Resale'].tolist())

seasonal_labels = json.dumps(['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'])
seasonal_margins = json.dumps(seasonal['Avg_Margin'].tolist())
seasonal_resale = json.dumps(seasonal['Avg_Resale'].tolist())
seasonal_days = json.dumps(seasonal['Avg_Days'].tolist())

# Build tables
def build_model_table():
    rows = []
    for _, r in model_stats.iterrows():
        rows.append(f"""<tr>
            <td>{r['Shoe_Model']}</td>
            <td class="text-center">{r['Transactions']:,}</td>
            <td class="text-right">${r['Avg_Retail']:,.2f}</td>
            <td class="text-right">${r['Avg_Resale']:,.2f}</td>
            <td class="text-right">{fmt_dollar(r['Avg_Margin'])}</td>
            <td class="text-right">{fmt_ratio(r['Avg_Ratio'])}</td>
            <td class="text-right">{fmt_pct(r['Above_Retail_Pct']*100)}</td>
        </tr>""")
    return "\n".join(rows)

def build_colorway_table():
    rows = []
    for _, r in colorway_stats.iterrows():
        rows.append(f"""<tr>
            <td>{r['Colorway']}</td>
            <td class="text-center">{r['Transactions']:,}</td>
            <td class="text-right">${r['Avg_Retail']:,.2f}</td>
            <td class="text-right">${r['Avg_Resale']:,.2f}</td>
            <td class="text-right">{fmt_dollar(r['Avg_Margin'])}</td>
            <td class="text-right">{fmt_ratio(r['Avg_Ratio'])}</td>
            <td class="text-right">{fmt_pct(r['Above_Retail_Pct']*100)}</td>
        </tr>""")
    return "\n".join(rows)

def build_condition_table():
    rows = []
    for _, r in condition_stats.iterrows():
        rows.append(f"""<tr>
            <td>{r['Condition']}</td>
            <td class="text-center">{r['Transactions']:,}</td>
            <td class="text-right">${r['Avg_Retail']:,.2f}</td>
            <td class="text-right">${r['Avg_Resale']:,.2f}</td>
            <td class="text-right">{fmt_dollar(r['Avg_Margin'])}</td>
            <td class="text-right">{fmt_ratio(r['Avg_Ratio'])}</td>
            <td class="text-right">{fmt_pct(r['Above_Retail_Pct']*100)}</td>
            <td class="text-right">{r['Avg_Days']:.1f}</td>
        </tr>""")
    return "\n".join(rows)

def build_channel_table():
    rows = []
    for _, r in channel_stats.iterrows():
        rows.append(f"""<tr>
            <td>{r['Sales_Channel']}</td>
            <td class="text-center">{r['Transactions']:,}</td>
            <td class="text-right">${r['Avg_Resale']:,.2f}</td>
            <td class="text-right">{fmt_dollar(r['Avg_Margin'])}</td>
            <td class="text-right">{fmt_pct(r['Above_Retail_Pct']*100)}</td>
            <td class="text-right">{r['Avg_Days']:.1f}</td>
            <td class="text-right">{r['Median_Days']:.1f}</td>
            <td class="text-right">${r['Daily_Margin']:,.2f}</td>
        </tr>""")
    return "\n".join(rows)

def build_yearly_table():
    rows = []
    for yr, r in yearly_summary.iterrows():
        rows.append(f"""<tr>
            <td class="text-center">{yr}</td>
            <td class="text-center">{r['Transactions']:,}</td>
            <td class="text-right">${r['Avg_Retail']:,.2f}</td>
            <td class="text-right">${r['Avg_Resale']:,.2f}</td>
            <td class="text-right">{fmt_dollar(r['Avg_Margin'])}</td>
            <td class="text-right">{r['Avg_Days']:.1f}</td>
        </tr>""")
    return "\n".join(rows)

def build_condition_model_table():
    models = condition_model.index.tolist()
    conds = condition_model.columns.tolist()
    header = "<tr><th>Model</th>" + "".join(f"<th class='text-center'>{c}</th>" for c in conds) + "</tr>"
    rows = []
    for m in models:
        cells = f"<td><strong>{m}</strong></td>"
        for c in conds:
            val = condition_model.loc[m, c]
            cells += f"<td class='text-right'>{fmt_dollar(val)}</td>"
        rows.append(f"<tr>{cells}</tr>")
    return header + "\n" + "\n".join(rows)

def build_channel_condition_table():
    channels = channel_stats['Sales_Channel'].tolist()
    conds = ['Deadstock (Brand New)', 'VNDS (Very Near Deadstock)', 'Used']
    header = "<tr><th>Channel</th>" + "".join(f"<th class='text-center'>{c.split('(')[0].strip()}</th>" for c in conds) + "</tr>"
    rows = []
    for ch in channels:
        cells = f"<td><strong>{ch}</strong></td>"
        for c in conds:
            subset = channel_condition[(channel_condition['Sales_Channel'] == ch) & (channel_condition['Condition'] == c)]
            if len(subset) > 0:
                margin = subset['Avg_Margin'].values[0]
                days = subset['Avg_Days'].values[0]
                cells += f"<td class='text-right'>{fmt_dollar(margin)}<br><span class='text-muted'>({days:.0f}d)</span></td>"
            else:
                cells += "<td class='text-right'>—</td>"
        rows.append(f"<tr>{cells}</tr>")
    return header + "\n" + "\n".join(rows)

def build_seasonal_table():
    months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
    rows = []
    for _, r in seasonal.iterrows():
        rows.append(f"""<tr>
            <td>{months[int(r['MonthOfYear'])-1]}</td>
            <td class="text-center">{r['Transactions']:,}</td>
            <td class="text-right">{fmt_dollar(r['Avg_Margin'])}</td>
            <td class="text-right">${r['Avg_Resale']:,.2f}</td>
            <td class="text-right">{r['Avg_Days']:.1f}</td>
        </tr>""")
    return "\n".join(rows)

# ─── Compose HTML ───
html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Air Jordan Sneaker Resale Market Analysis (2023–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.4/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --bg: #0f1117;
    --surface: #1a1d27;
    --surface2: #242836;
    --border: #2e3345;
    --text: #e4e6ef;
    --text-muted: #8b8fa3;
    --accent: #6366f1;
    --accent2: #818cf8;
    --green: #22c55e;
    --red: #ef4444;
    --amber: #f59e0b;
    --cyan: #06b6d4;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    font-size: 14px;
  }}
  .container {{ max-width: 1200px; margin: 0 auto; padding: 0 24px; }}

  /* Header */
  .report-header {{
    background: linear-gradient(135deg, #1a1d27 0%, #2d1f5e 50%, #1a1d27 100%);
