  /* Sections */
  .section {{
    margin-bottom: 48px;
  }}
  .section-header {{
    display: flex;
    align-items: baseline;
    gap: 12px;
    margin-bottom: 20px;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--border);
  }}
  .section-number {{
    font-size: 12px;
    font-weight: 600;
    color: var(--accent);
    letter-spacing: 1px;
  }}
  .section-title {{
    font-size: 20px;
    font-weight: 700;
    color: #fff;
  }}
  .section-objective {{
    font-size: 13px;
    color: var(--text-muted);
    margin-bottom: 20px;
  }}

  /* Chart containers */
  .chart-grid {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 20px;
  }}
  .chart-grid.single {{ grid-template-columns: 1fr; }}
  .chart-box {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
  }}
  .chart-box h3 {{
    font-size: 13px;
    font-weight: 600;
    color: var(--text-muted);
    margin-bottom: 12px;
    text-transform: uppercase;
