      <div class="kpi-sub">{top_colorway}</div>
    </div>
  </div>

  <!-- ─── Section 1: Market Overview ─── -->
  <section class="section">
    <div class="section-header">
      <span class="section-number">01</span>
      <h2 class="section-title">Market Overview & Transaction Summary</h2>
    </div>
    <p class="section-objective">High-level summary of total transactions, date range coverage, average retail vs. resale prices, and overall profit margin distribution.</p>

    <div class="insight-grid">
      <div class="insight-card">
        <div class="insight-label">Total Transactions</div>
        <div class="insight-value">{total_transactions:,}</div>
        <div class="insight-note">{date_min} to {date_max}</div>
      </div>
      <div class="insight-card">
        <div class="insight-label">Average Retail Price</div>
        <div class="insight-value">${avg_retail:,.2f}</div>
      </div>
      <div class="insight-card">
        <div class="insight-label">Average Resale Price</div>
        <div class="insight-value">${avg_resale:,.2f}</div>
      </div>
      <div class="insight-card">
        <div class="insight-label">Profitable Transactions</div>
        <div class="insight-value" style="color:var(--green)">{pct_positive}%</div>
        <div class="insight-note">{pct_negative}% sold at a loss</div>
      </div>
