    <div class="table-wrapper">
      <h3>Yearly Performance Summary</h3>
      <table>
        <thead>
          <tr><th>Year</th><th class="text-center">Txns</th><th class="text-right">Avg Retail</th><th class="text-right">Avg Resale</th><th class="text-right">Avg Margin</th><th class="text-right">Avg Days</th></tr>
        </thead>
        <tbody>{build_yearly_table()}</tbody>
      </table>
