  <!-- ─── Section 2: Model & Colorway ─── -->
  <section class="section">
    <div class="section-header">
      <span class="section-number">02</span>
      <h2 class="section-title">Performance by Shoe Model & Colorway</h2>
    </div>
    <p class="section-objective">Rank Air Jordan models and colorways by average resale price, profit margin, and transaction volume. Identify the highest-premium and below-retail segments.</p>

    <div class="chart-grid">
      <div class="chart-box">
        <h3>Average Profit Margin by Model</h3>
        <div class="chart-container"><canvas id="modelMarginChart"></canvas></div>
      </div>
      <div class="chart-box">
        <h3>Resale-to-Retail Ratio by Model</h3>
        <div class="chart-container"><canvas id="modelRatioChart"></canvas></div>
      </div>
    </div>

    <div class="chart-grid">
      <div class="chart-box">
        <h3>Average Profit Margin by Colorway</h3>
