    </div>

    <div class="table-wrapper">
      <h3>Model Performance Ranking</h3>
      <table>
        <thead>
          <tr><th>Model</th><th class="text-center">Txns</th><th class="text-right">Avg Retail</th><th class="text-right">Avg Resale</th><th class="text-right">Avg Margin</th><th class="text-right">Ratio</th><th class="text-right">Above Retail %</th></tr>
        </thead>
