    <div class="table-wrapper">
      <h3>Colorway Performance Ranking</h3>
      <table>
        <thead>
          <tr><th>Colorway</th><th class="text-center">Txns</th><th class="text-right">Avg Retail</th><th class="text-right">Avg Resale</th><th class="text-right">Avg Margin</th><th class="text-right">Ratio</th><th class="text-right">Above Retail %</th></tr>
        </thead>
        <tbody>{build_colorway_table()}</tbody>
      </table>
    </div>
  </section>

  <!-- ─── Section 3: Condition Impact ─── -->
  <section class="section">
    <div class="section-header">
      <span class="section-number">03</span>
      <h2 class="section-title">Impact of Shoe Condition on Resale Value</h2>
    </div>
    <p class="section-objective">Quantify how Deadstock, VNDS, and Used conditions affect resale price premiums and the probability of selling above retail.</p>

    <div class="insight-grid">
      <div class="insight-card">
        <div class="insight-label">Deadstock → VNDS Premium Gap</div>
        <div class="insight-value" style="color:var(--green)">+${ds_vnds_gap:,.2f}</div>
        <div class="insight-note">Avg margin difference between DS and VNDS</div>
      </div>
      <div class="insight-card">
        <div class="insight-label">VNDS → Used Premium Gap</div>
        <div class="insight-value" style="color:var(--green)">+${vnds_used_gap:,.2f}</div>
        <div class="insight-note">Avg margin difference between VNDS and Used</div>
      </div>
      <div class="insight-card">
        <div class="insight-label">Deadstock → Used Premium Gap</div>
        <div class="insight-value" style="color:var(--green)">+${ds_used_gap:,.2f}</div>
        <div class="insight-note">Full condition spread — DS vs. Used</div>
      </div>
    </div>

    <div class="chart-grid">
      <div class="chart-box">
        <h3>Average Margin by Condition</h3>
        <div class="chart-container"><canvas id="conditionMarginChart"></canvas></div>
      </div>
      <div class="chart-box">
        <h3>% Above Retail by Condition</h3>
        <div class="chart-container"><canvas id="conditionAboveChart"></canvas></div>
      </div>
    </div>

    <div class="chart-grid">
      <div class="chart-box">
        <h3>Resale-to-Retail Ratio by Condition</h3>
        <div class="chart-container"><canvas id="conditionRatioChart"></canvas></div>
      </div>
      <div class="chart-box">
        <h3>Avg Days in Inventory by Condition</h3>
        <div class="chart-container"><canvas id="conditionDaysChart"></canvas></div>
      </div>
    </div>

    <div class="table-wrapper">
      <h3>Condition Performance Summary</h3>
      <table>
        <thead>
          <tr><th>Condition</th><th class="text-center">Txns</th><th class="text-right">Avg Retail</th><th class="text-right">Avg Resale</th><th class="text-right">Avg Margin</th><th class="text-right">Ratio</th><th class="text-right">Above Retail %</th><th class="text-right">Avg Days</th></tr>
        </thead>
        <tbody>{build_condition_table()}</tbody>
      </table>
    </div>

    <div class="table-wrapper">
      <h3>Avg Margin by Model × Condition</h3>
      <table>
        <thead>{build_condition_model_table().split('</tr>')[0] + '</tr>'}</thead>
        <tbody>{'<tr>'.join(build_condition_model_table().split('<tr>')[1:])}</tbody>
      </table>
    </div>
  </section>

  <!-- ─── Section 4: Channel Performance ─── -->
  <section class="section">
    <div class="section-header">
      <span class="section-number">04</span>
      <h2 class="section-title">Sales Channel Performance & Inventory Velocity</h2>
    </div>
    <p class="section-objective">Compare sales channels on average resale price, profit margin, and days in inventory to determine which platforms move product fastest and most profitably.</p>

    <div class="chart-grid">
      <div class="chart-box">
        <h3>Avg Margin vs. Avg Days in Inventory</h3>
        <div class="chart-container"><canvas id="channelBubbleChart"></canvas></div>
      </div>
      <div class="chart-box">
        <h3>Avg Profit Margin by Channel</h3>
        <div class="chart-container"><canvas id="channelMarginChart"></canvas></div>
      </div>
    </div>

    <div class="chart-grid">
      <div class="chart-box">
        <h3>% Transactions Above Retail by Channel</h3>
        <div class="chart-container"><canvas id="channelAboveChart"></canvas></div>
      </div>
      <div class="chart-box">
        <h3>Avg Days in Inventory by Channel</h3>
