  <!-- ─── Section 5: Temporal Trends ─── -->
  <section class="section">
    <div class="section-header">
      <span class="section-number">05</span>
      <h2 class="section-title">Temporal Trends & Seasonality</h2>
    </div>
    <p class="section-objective">Analyze monthly and yearly trends in resale prices, profit margins, and transaction volumes to identify seasonal patterns and market momentum shifts from 2023 to 2026.</p>

    <div class="chart-grid single">
      <div class="chart-box">
        <h3>Monthly Avg Resale Price & Profit Margin</h3>
        <div class="chart-container" style="height:320px"><canvas id="monthlyTrendChart"></canvas></div>
      </div>
    </div>

    <div class="chart-grid">
