        <div class="chart-container"><canvas id="quarterlyMarginChart"></canvas></div>
      </div>
      <div class="chart-box">
        <h3>Seasonal Pattern (Month-of-Year Avg)</h3>
        <div class="chart-container"><canvas id="seasonalChart"></canvas></div>
      </div>
    </div>

    <div class="chart-grid">
      <div class="chart-box">
