  </div>
</footer>

<script>
// ─── Chart.js Global Config ───
Chart.defaults.color = '#8b8fa3';
Chart.defaults.borderColor = '#2e3345';
Chart.defaults.font.family = "-apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif";
Chart.defaults.font.size = 11;
Chart.defaults.plugins.legend.labels.boxWidth = 12;
Chart.defaults.plugins.legend.labels.padding = 16;

const greenGrad = (ctx) => {{
  const g = ctx.chart.ctx.createLinearGradient(0, 0, 0, ctx.chart.height);
  g.addColorStop(0, 'rgba(34,197,94,0.8)');
  g.addColorStop(1, 'rgba(34,197,94,0.1)');
  return g;
}};
const redGrad = (ctx) => {{
  const g = ctx.chart.ctx.createLinearGradient(0, 0, 0, ctx.chart.height);
  g.addColorStop(0, 'rgba(239,68,68,0.8)');
  g.addColorStop(1, 'rgba(239,68,68,0.1)');
  return g;
}};

// ─── 1. Margin Distribution ───
new Chart(document.getElementById('marginDistChart'), {{
  type: 'bar',
  data: {{
    labels: {margin_dist_labels},
    datasets: [{{
      label: 'Transactions',
      data: {margin_dist_values},
      backgroundColor: {margin_dist_values}.map(v => v > 0 ? 'rgba(99,102,241,0.7)' : 'rgba(99,102,241,0.7)'),
      borderColor: '#6366f1',
      borderWidth: 1,
      borderRadius: 4
    }}]
  }},
  options: {{
    responsive: true,
    plugins: {{ legend: {{ display: false }} }},
