    Avg_Margin=('Profit_Margin_USD', 'mean'),
    Median_Margin=('Profit_Margin_USD', 'median'),
    Avg_Ratio=('Resale_Retail_Ratio', 'mean'),
    Above_Retail_Pct=('Above_Retail', 'mean'),
    Avg_Days=('Days_in_Inventory', 'mean')
).round(2).reset_index()

# Condition by model
condition_model = df.groupby(['Shoe_Model', 'Condition'])['Profit_Margin_USD'].mean().round(2).unstack(fill_value=0)

# Condition premium gaps
ds_margin = condition_stats.loc[condition_stats['Condition'].str.contains('Deadstock'), 'Avg_Margin'].values[0]
vnds_margin = condition_stats.loc[condition_stats['Condition'].str.contains('VNDS'), 'Avg_Margin'].values[0]
used_margin = condition_stats.loc[condition_stats['Condition'].str.contains('Used'), 'Avg_Margin'].values[0]
ds_vnds_gap = round(ds_margin - vnds_margin, 2)
vnds_used_gap = round(vnds_margin - used_margin, 2)
ds_used_gap = round(ds_margin - used_margin, 2)

# ─── Section 4: Channel Performance ───
