    Avg_Days=('Days_in_Inventory', 'mean'),
    Transactions=('Transaction_ID', 'count')
).round(2).reset_index()

# ─── Build HTML ───

# Helper: format dollar
def fmt_dollar(val):
    if val < 0:
        return f"<span style='color:#ef4444'>-${abs(val):,.2f}</span>"
    elif val > 0:
        return f"<span style='color:#22c55e'>+${val:,.2f}</span>"
    return "$0.00"

def fmt_pct(val):
    return f"{val:.1f}%"

def fmt_ratio(val):
